    "/ad_groups/{id}/duplicate": {
      post: {
        description: "Starts copying an ad group and returns the copies in `duplicating` status. Poll each returned ad group until it leaves `duplicating`: it then takes the source's `active` or `paused` status, or, if the copy could not be completed, is deleted and returns 404.",
        operationId: "duplicate",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            description: "The ad group ID.",
            in: "path",
            name: "id",
            required: true,
            schema: {
              type: "string"
            }
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  count: {
                    description: "Number of copies to create (1-10). Defaults to 1.",
                    example: 2,
                    type: "integer"
                  },
                  preserve_engagement: {
                    description: "Whether the copied ads keep the original posts' engagement (likes, comments, shares). Defaults to false.",
                    example: true,
                    type: "boolean"
                  },
                  target_ad_campaign_id: {
                    description: "Campaign to duplicate into. Must belong to the same account and be compatible with the ad group's targeting and goals. Defaults to the ad group's own campaign.",
                    example: "adcamp_xxxxxxxxxxxxxx",
                    type: "string"
                  }
                },
                type: "object"
              }
            }
          }
        },
        responses: {
          "201": {
            content: {
              "application/json": {
                schema: {
                  properties: {
                    data: {
                      items: {
                        $ref: "#/components/schemas/AdGroup"
                      },
                      type: "array"
                    }
                  },
                  required: ["data"],
                  type: "object"
                }
              }
            },
            description: "ad group duplication started"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "a duplication is already running for this ad group"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "ad group not found"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            bearerAuth: ["ad_campaign:create"]
          }
        ],
        summary: "Duplicate an Ad Group",
        tags: ["Ad Groups"],
        "x-codeSamples": [
          {
            lang: "TypeScript",
            source: 'import { WhopClient } from "@whop/sdk";\n\nconst client = new WhopClient({ token: "YOUR_TOKEN", apiVersionDate: "2026-08-21-1", idempotencyKey: "YOUR_IDEMPOTENCY_KEY" });\nawait client.adGroups.duplicate({\n    id: "id"\n});\n'
          }
        ]
      }
    },
