    "/ads/{id}/duplicate": {
      post: {
        description: "Copies an ad into its own ad group or into another one. Copies keep the source ad's active or paused state.",
        operationId: "duplicate",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            description: "The ad ID.",
            in: "path",
            name: "id",
            required: true,
            schema: {
              type: "string"
            }
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  count: {
                    description: "Number of copies to create (1-10). Defaults to 1.",
                    example: 2,
                    type: "integer"
                  },
                  preserve_engagement: {
                    description: "Whether the copies keep the original post's engagement (likes, comments, shares). Defaults to false.",
                    example: true,
                    type: "boolean"
                  },
                  target_ad_group_id: {
                    description: "Ad group to duplicate into, which must belong to the same account and be compatible with the ad. Defaults to the ad's own ad group.",
                    example: "adgrp_xxxxxxxxxxxxxx",
                    type: "string"
                  }
                },
                type: "object"
              }
            }
          }
        },
        responses: {
          "201": {
            content: {
              "application/json": {
                schema: {
                  properties: {
                    data: {
                      items: {
                        $ref: "#/components/schemas/Ad"
                      },
                      type: "array"
                    }
                  },
                  required: ["data"],
                  type: "object"
                }
              }
            },
            description: "ad duplicated"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "target ad group on a different ad account"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "ad not found"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            bearerAuth: ["ad_campaign:create"]
          }
        ],
        summary: "Duplicate an Ad",
        tags: ["Ads"],
        "x-codeSamples": [
          {
            lang: "TypeScript",
            source: 'import { WhopClient } from "@whop/sdk";\n\nconst client = new WhopClient({ token: "YOUR_TOKEN", apiVersionDate: "2026-08-21-1", idempotencyKey: "YOUR_IDEMPOTENCY_KEY" });\nawait client.ads.duplicate({\n    id: "id"\n});\n'
          }
        ]
      }
    },
