      post: {
        description: "Uploads a new build artifact for an app. Upload the file first with `POST /files` or a direct upload, then reference it in `attachment`.",
        operationId: "create",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  app_id: {
                    description: "The app to create the build for, prefixed `app_`. Defaults to the app behind the presented credential.",
                    example: "app_xxxxxxxxxxxxxx",
                    type: "string"
                  },
                  attachment: {
                    description: "The uploaded build file: pass `id` for an existing file or `direct_upload_id` for a completed direct upload. iOS and Android builds take a .zip bundle; web builds take a JavaScript file or a .zip archive of the hosted site.",
                    properties: {
                      direct_upload_id: {
                        description: "The signed id of a completed direct upload.",
                        example: "eyJfcmFpbHMiOnsiZGF0YSI6MSwicHVyIjoiYmxvYl9pZCJ9fQ==--xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
                        type: "string"
                      },
                      id: {
                        description: "The tag of an already-uploaded file.",
                        example: "file_xxxxxxxxxxxxxx",
                        type: "string"
                      }
                    },
                    type: "object"
                  },
                  checksum: {
                    description: "A client-generated checksum of the build file, used to verify file integrity when unpacked.",
                    example: "xxxxxxxxxxxxxxx",
                    type: "string"
                  },
                  platform: {
                    description: "The target platform for the build.",
                    enum: ["ios", "android", "web"],
                    example: "web",
                    type: "string"
                  },
                  source_attachment: {
                    description: "An optional compressed archive (.zip or .gz) of the source code that produced this build, stored alongside the build so it can be downloaded later. Referenced like `attachment`, and must be a different file.",
                    properties: {
                      direct_upload_id: {
                        description: "The signed id of a completed direct upload.",
                        example: "eyJfcmFpbHMiOnsiZGF0YSI6MSwicHVyIjoiYmxvYl9pZCJ9fQ==--xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
                        type: "string"
                      },
                      id: {
                        description: "The tag of an already-uploaded file.",
                        example: "file_xxxxxxxxxxxxxx",
                        type: "string"
                      }
                    },
                    type: "object"
                  },
                  supported_app_view_types: {
                    description: "The view types this build supports. Only list the ones its code implements.",
                    items: {
                      enum: [
                        "hub",
                        "discover",
                        "dash",
                        "dashboard",
                        "analytics",
                        "skills",
                        "openapi"
                      ],
                      example: "hub",
                      type: "string"
                    },
                    type: "array"
                  }
                },
                required: ["attachment", "checksum", "platform"],
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  $ref: "#/components/schemas/AppBuild"
                }
              }
            },
            description: "app build created"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "the request body is invalid"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "missing or invalid authentication"
          },
          "403": {
            $ref: "#/components/responses/Forbidden",
            description: "credential lacks the build-management scope"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            bearerAuth: []
          },
          {
            bearerAuth: ["developer:manage_builds"]
          }
        ],
        summary: "Create App Build",
        tags: ["App Builds"],
        "x-mint": {
          metadata: {
            sidebarTitle: "Create"
          }
        },
        "x-codeSamples": [
          {
            lang: "TypeScript",
            source: 'import { WhopClient } from "@whop/sdk";\n\nconst client = new WhopClient({ token: "YOUR_TOKEN", apiVersionDate: "2026-08-21-1", idempotencyKey: "YOUR_IDEMPOTENCY_KEY" });\nawait client.appBuilds.create({\n    attachment: {},\n    checksum: "xxxxxxxxxxxxxxx",\n    platform: "ios"\n});\n'
          }
        ]
      }
