      post: {
        description: "Registers a new app on the Whop developer platform. Apps provide custom experiences that can be added to products.",
        operationId: "create",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  account_id: {
                    description: "The account to create the app for (`biz_` tag). Defaults to the account behind the presented credential.",
                    example: "biz_xxxxxxxxxxxxxx",
                    type: "string"
                  },
                  app_type: {
                    default: "b2c_app",
                    description: "The type of app to create. Defaults to `b2c_app`.",
                    enum: [
                      "b2b_app",
                      "b2c_app",
                      "company_app",
                      "component",
                      "website"
                    ],
                    example: "website",
                    type: "string"
                  },
                  base_url: {
                    description: "The base production URL where the app is hosted, such as `https://myapp.example.com`.",
                    type: ["string", "null"]
                  },
                  domain_id: {
                    description: "A domain on the account (`dom_` tag) to serve the app at, such as a whop.site address claimed with `POST /domains`. Required with `template_id`.",
                    example: "dom_xxxxxxxxxxxxxx",
                    type: ["string", "null"]
                  },
                  icon: {
                    description: "The icon image for the app in PNG, JPEG, or GIF format, referencing an uploaded file: `{ id }` for an existing attachment or `{ direct_upload_id }` for a new direct upload.",
                    properties: {
                      direct_upload_id: {
                        description: "The signed id of a completed direct upload.",
                        example: "eyJfcmFpbHMiOnsiZGF0YSI6MSwicHVyIjoiYmxvYl9pZCJ9fQ==--xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
                        type: "string"
                      },
                      id: {
                        description: "The tag of an already-uploaded attachment.",
                        example: "file_xxxxxxxxxxxxxx",
                        type: "string"
                      }
                    },
                    type: "object"
                  },
                  imported_from_url: {
                    description: "The address of the existing website this app is imported from, such as `https://shop.example.com`. Must be an `http` or `https` URL.",
                    example: "https://shinetime.example",
                    type: ["string", "null"]
                  },
                  name: {
                    description: "The display name for the app, shown to users on the app store and product pages.",
                    example: "Shine Time Booking",
                    type: "string"
                  },
                  redirect_uris: {
                    description: "The whitelisted OAuth callback URLs that users are redirected to after authorizing the app.",
                    items: {
                      example: "https://booking.shinetime.example/oauth/callback",
                      type: "string"
                    },
                    type: "array"
                  },
                  route: {
                    deprecated: true,
                    description: "Deprecated: claim an address with `POST /domains` and pass `domain_id`. The subdomain route where the app's hosted web builds are served, such as `myapp` for myapp.whop.site.",
                    example: "shine-time-booking-site",
                    type: ["string", "null"]
                  }
                },
                required: ["name"],
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  $ref: "#/components/schemas/App"
                }
              }
            },
            description: "app created"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "the request body is invalid"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "missing or invalid authentication"
          },
          "403": {
            $ref: "#/components/responses/Forbidden",
            description: "credential lacks the app-creation scope"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "no account with that ID exists"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            bearerAuth: ["developer:create_app"]
          }
        ],
        summary: "Create App",
        tags: ["Apps"],
        "x-mint": {
          metadata: {
            sidebarTitle: "Create"
          }
        },
        "x-codeSamples": [
          {
            lang: "TypeScript",
            source: 'import { WhopClient } from "@whop/sdk";\n\nconst client = new WhopClient({ token: "YOUR_TOKEN", apiVersionDate: "2026-08-21-1", idempotencyKey: "YOUR_IDEMPOTENCY_KEY" });\nawait client.apps.create({\n    name: "Shine Time Booking"\n});\n'
          }
        ]
      }
