    "/apps/{id}/permissions": {
      patch: {
        description: "Replaces the set of permissions the app requests from users when they install it. Requires a user session: the `developer:update_app_authorization` scope cannot be delegated to API keys. Sensitive permissions require step-up verification.",
        operationId: "permissions",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            description: "App ID, prefixed `app_`.",
            in: "path",
            name: "id",
            required: true,
            schema: {
              type: "string"
            }
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  requested_permissions: {
                    description: "The full set of permissions the app requests on install; permissions not listed are removed.",
                    items: {
                      properties: {
                        action: {
                          description: "The permission action, for example `company:basic:read`.",
                          example: "company:basic:read",
                          type: "string"
                        },
                        is_required: {
                          description: "Whether installing the app requires granting this permission.",
                          example: true,
                          type: "boolean"
                        },
                        justification: {
                          description: "Why the app needs this permission (20-512 characters), shown to the installing user.",
                          example: "Reads basic account info to render the dashboard home.",
                          type: "string"
                        }
                      },
                      required: ["action", "is_required", "justification"],
                      type: "object"
                    },
                    type: "array"
                  }
                },
                required: ["requested_permissions"],
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  $ref: "#/components/schemas/App"
                }
              }
            },
            description: "requested permissions updated"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "the request body is invalid"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "missing or invalid authentication"
          },
          "403": {
            $ref: "#/components/responses/Forbidden",
            description: "credential lacks the app-authorization scope"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "no app with that ID exists"
          }
        },
        security: [
          {
            whopSessionAuth: ["developer:update_app_authorization"]
          }
        ],
        summary: "Update App Permissions",
        tags: ["Apps"],
        "x-whop-credentials": [],
        "x-mint": {
          metadata: {
            sidebarTitle: "Update Permissions"
          }
        },
        "x-codeSamples": [
          {
            lang: "TypeScript",
            source: 'import { WhopClient } from "@whop/sdk";\n\nconst client = new WhopClient({ token: "YOUR_TOKEN", apiVersionDate: "2026-08-21-1", idempotencyKey: "YOUR_IDEMPOTENCY_KEY" });\nawait client.apps.updatePermissions({\n    id: "id",\n    requested_permissions: [{\n            action: "company:basic:read",\n            is_required: true,\n            justification: "Reads basic account info to render the dashboard home."\n        }]\n});\n'
          }
        ]
      }
    },
