    "/cashback_rule": {
      post: {
        description: "Creates a future-dated card cashback rule for your direct connected accounts, funded by the authenticated platform account. Creating a rule does not transfer funds; pay cashback out with `POST /cashback_rules/payout`. Requires `payout:transfer_funds`. Supports `Idempotency-Key` for safe retries.",
        operationId: "create",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            description: "Client-generated key for replaying the same request safely for 24 hours.",
            in: "header",
            name: "Idempotency-Key",
            required: false,
            schema: {
              maxLength: 255,
              minLength: 1,
              type: "string"
            }
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                additionalProperties: false,
                properties: {
                  description: {
                    description: "Optional description of the rule.",
                    example: "Software cashback",
                    maxLength: 255,
                    type: ["string", "null"]
                  },
                  expires_at: {
                    description: "Exclusive end, strictly later than starts_at. Omit or set null for no expiration.",
                    example: "2026-01-01T12:00:00.000Z",
                    format: "date-time",
                    type: ["string", "null"]
                  },
                  merchant_category_code: {
                    description: "Four-digit MCC, including leading zeros. Null matches any MCC. When both merchant filters are absent, scoped_account_id is required.",
                    example: "5734",
                    pattern: "^[0-9]{4}$",
                    type: ["string", "null"]
                  },
                  merchant_name: {
                    description: "Raw merchant name reported by the card provider, not the enriched display name. Omit or set null to match any merchant name. Supplied names must contain a non-whitespace character and match together with any MCC filter.",
                    example: "ACME SOFTWARE",
                    maxLength: 128,
                    minLength: 1,
                    type: ["string", "null"]
                  },
                  rate_bps: {
                    description: "Cashback rate in basis points: 500 means 5%.",
                    example: 500,
                    maximum: 1e4,
                    minimum: 1,
                    type: "integer"
                  },
                  scoped_account_id: {
                    description: "Account ID, prefixed `biz_`, of one direct connected account to limit the rule to. Required when both merchant filters are omitted or `null`, in which case the rule matches all eligible transactions for that account. Otherwise, omit or set `null` to designate all direct connected accounts.",
                    pattern: "^biz_",
                    type: ["string", "null"]
                  },
                  starts_at: {
                    description: "Inclusive start, strictly later than the current time, as an ISO 8601 timestamp.",
                    example: "2026-01-01T12:00:00.000Z",
                    format: "date-time",
                    type: "string"
                  }
                },
                required: ["rate_bps", "starts_at"],
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "201": {
            content: {
              "application/json": {
                schema: {
                  $ref: "#/components/schemas/CashbackRule"
                }
              }
            },
            description: "cashback rule created"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "invalid rule"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "authentication required"
          },
          "403": {
            $ref: "#/components/responses/Forbidden",
            description: "insufficient funding permissions"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "connected account not found"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            bearerAuth: []
          }
        ],
        summary: "Create Cashback Rule",
        tags: ["Cashback Rules"],
        "x-mint": {
          metadata: {
            sidebarTitle: "Create"
          }
        }
      }
    },
