    "/experiments/{id}/activate": {
      post: {
        description: "Starts (or resumes) an experiment or feature flag so evaluation begins serving it. Activating a draft stamps `started_at`; resuming a paused experiment keeps the original start. Only drafts and paused experiments can be activated. Requires `experiment:manage` on the owning account.",
        operationId: "activate",
        parameters: [
          {
            description: "Owning account ID. Required when id is a flag key; optional for an expt_ ID.",
            in: "query",
            name: "account_id",
            required: false,
            schema: {
              type: "string"
            }
          },
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            description: "The experiment identifier \u2014 the `expt_` id or the flag_key handle.",
            in: "path",
            name: "id",
            required: true,
            schema: {
              type: "string"
            }
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  duration_days: {
                    description: "Reporting window length in days. Omit to use the default. This does not automatically end the experiment.",
                    example: 30,
                    nullable: true,
                    type: "integer"
                  }
                },
                type: "object"
              }
            }
          }
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  $ref: "#/components/schemas/Experiment"
                }
              }
            },
            description: "experiment activated"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "transition not allowed"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            bearerAuth: []
          }
        ],
        summary: "Activate Experiment",
        tags: ["Experiments"],
        "x-mint": {
          metadata: {
            sidebarTitle: "Activate"
          }
        }
      }
    },
    "/experiments/{id}/end": {
      post: {
        description: "Concludes the experiment and records required `findings`. Pass `winning_arm` to serve the winning treatment to everyone; omit it when control won. Ended experiments cannot restart, but may be ended again to correct the winner. Requires `experiment:manage` on the owning account.",
        operationId: "end",
        parameters: [
          {
            description: "Owning account ID. Required when id is a flag key; optional for an expt_ ID.",
            in: "query",
            name: "account_id",
            required: false,
            schema: {
              type: "string"
            }
          },
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            description: "The experiment identifier \u2014 the `expt_` id or the flag_key handle.",
            in: "path",
            name: "id",
            required: true,
            schema: {
              type: "string"
            }
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  findings: {
                    description: "What you learned and why you chose this outcome. Required.",
                    example: "Treatment lifted signups 12%, shipping it to everyone.",
                    type: "string"
                  },
                  winning_arm: {
                    description: "The treatment that won. Setting it rolls that arm out: every later evaluation returns it to every caller, ignoring targeting and allocation, and exposures stop being recorded. Omit it when control won \u2014 an ended experiment with no winning arm evaluates to `control` for everyone, so ending again without one also reverts a rollout recorded by mistake. Not accepted on feature flags, which evaluate to disabled once ended.",
                    example: "treatment",
                    nullable: true,
                    type: "string"
                  }
                },
                required: ["findings"],
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  $ref: "#/components/schemas/Experiment"
                }
              }
            },
            description: "experiment ended"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "winning_arm is not a treatment of this experiment"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            bearerAuth: []
          }
        ],
        summary: "End Experiment",
        tags: ["Experiments"]
      }
    },
