    "/external_accounts/connect": {
      post: {
        description: "Starts an OAuth connection flow and returns an `authorize_url` to send the user to, where they connect an external account. Personal profile connections must be completed in a browser signed in as the Whop user who started the flow.",
        operationId: "connect",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  account_id: {
                    description: "The Account (biz_ identifier) to connect the external account for. An account-scoped API key may omit this to default to its own account. Omit for user profile connections.",
                    example: "biz_xxxxxxxxxxxxxx",
                    type: "string"
                  },
                  platform: {
                    description: "The platform to connect the external account on. Use `meta_business` to connect Meta Business assets, which is how Facebook Pages and Instagram accounts are connected \u2014 there is no separate `instagram` value. Use `tiktok` for TikTok accounts, `snapchat` for Snapchat Public Profiles, `linkedin` to connect the authenticated user\u2019s LinkedIn profile, `youtube` to connect their YouTube channel, or `x` to connect their X profile.",
                    enum: [
                      "meta_business",
                      "tiktok",
                      "linkedin",
                      "youtube",
                      "x",
                      "snapchat"
                    ],
                    example: "meta_business",
                    type: "string"
                  },
                  redirect_url: {
                    description: "Where to send the user once they finish connecting their accounts. Must be an `https` URL on whop.com; any other host is rejected. On success, the user is redirected with an `external_account_connected` query param naming the platform; if the connection fails, with an `external_account_error` query param instead. The same values also arrive as `social_account_connected` / `social_account_error`.",
                    example: "https://whop.com/dashboard/biz_xxxxxxxxxxxxxx/ads/settings",
                    type: "string"
                  },
                  scopes: {
                    description: "The connection purpose. For `meta_business` and `snapchat`, `advertise` is required and connects company advertising assets. For `linkedin`, `youtube`, and `x`, omit scopes to connect the authenticated user\u2019s profile; advertising is not supported. For `tiktok`, omit scopes to connect the authenticated user\u2019s profile, or pass `advertise` to connect company advertising assets. Profile connections still request the platform permissions needed to read the profile.",
                    items: {
                      enum: ["advertise"],
                      example: "advertise",
                      type: "string"
                    },
                    type: "array"
                  }
                },
                required: ["redirect_url", "platform"],
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  properties: {
                    authorize_url: {
                      description: "The OAuth authorization URL to redirect the user to.",
                      example: "https://www.facebook.com/v25.0/dialog/oauth",
                      type: "string"
                    }
                  },
                  required: ["authorize_url"],
                  type: "object"
                }
              }
            },
            description: "authorize url returned"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "unsupported platform"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "missing or invalid authentication"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            bearerAuth: ["social_account:create"]
          }
        ],
        summary: "Connect an External Account",
        tags: ["External Accounts"],
        "x-mint": {
          metadata: {
            sidebarTitle: "Connect"
          }
        }
      }
    },
