    "/livestreams": {
      get: {
        description: "Lists the livestreams in an experience, live and ended, newest first.",
        operationId: "list",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            description: "ID of a livestreams experience, prefixed `exp_`.",
            in: "query",
            name: "experience_id",
            required: true,
            schema: {
              type: "string"
            }
          },
          {
            description: "When `true`, only pinned livestreams, most recently pinned first. When `false`, only livestreams that are not pinned.",
            in: "query",
            name: "pinned",
            required: false,
            schema: {
              type: "boolean"
            }
          },
          {
            description: "When `true`, only ended livestreams that were recorded, including recordings still processing. `false` or omitted lists every livestream.",
            in: "query",
            name: "recorded",
            required: false,
            schema: {
              type: "boolean"
            }
          },
          {
            description: "Number of results to return from the start of the range.",
            in: "query",
            name: "first",
            required: false,
            schema: {
              default: 20,
              maximum: 100,
              type: "integer"
            }
          },
          {
            description: "Return results after this cursor. Use `page_info.end_cursor` from the previous response to fetch the next page.",
            in: "query",
            name: "after",
            required: false,
            schema: {
              type: "string"
            }
          },
          {
            description: "Number of results to return from the end of the range.",
            in: "query",
            name: "last",
            required: false,
            schema: {
              maximum: 100,
              type: "integer"
            }
          },
          {
            description: "Return results before this cursor. Use `page_info.start_cursor` from the previous response to fetch the previous page.",
            in: "query",
            name: "before",
            required: false,
            schema: {
              type: "string"
            }
          }
        ],
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  properties: {
                    data: {
                      items: {
                        $ref: "#/components/schemas/Livestream"
                      },
                      type: "array"
                    },
                    page_info: {
                      properties: {
                        end_cursor: {
                          example: null,
                          type: ["string", "null"]
                        },
                        has_next_page: {
                          example: false,
                          type: "boolean"
                        },
                        has_previous_page: {
                          example: false,
                          type: "boolean"
                        },
                        start_cursor: {
                          example: "WyJjdXJzb3IiLDFd",
                          type: ["string", "null"]
                        }
                      },
                      required: [
                        "end_cursor",
                        "start_cursor",
                        "has_next_page",
                        "has_previous_page"
                      ],
                      type: "object"
                    }
                  },
                  required: ["data", "page_info"],
                  type: "object"
                }
              }
            },
            description: "livestreams listed"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "missing or invalid authentication"
          },
          "403": {
            $ref: "#/components/responses/Forbidden",
            description: "no access to the experience"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "experience not found"
          }
        },
        security: [
          {
            bearerAuth: ["livestream:chat:read"]
          }
        ],
        summary: "List Livestreams",
        tags: ["Livestreams"],
        "x-mint": {
          metadata: {
            sidebarTitle: "List"
          }
        }
      }
    },
