    "/memberships/invite": {
      post: {
        description: "Emails one recipient an invitation to a free variant's membership. The invitation is bound to that recipient; after signing in, accepting it immediately grants the membership without checkout. This Experimental endpoint is available only to accounts enabled for membership invitations.",
        operationId: "invite",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                oneOf: [
                  {
                    properties: {
                      plan_id: {
                        description: "Free variant whose membership the recipient is invited to, prefixed `plan_`.",
                        example: "plan_xxxxxxxxxxxxxx",
                        type: "string"
                      },
                      user_id: {
                        description: "Recipient user ID, prefixed `user_`.",
                        example: "user_xxxxxxxxxxxxxx",
                        type: "string"
                      }
                    },
                    required: ["plan_id", "user_id"],
                    title: "InviteMembershipByUser",
                    type: "object"
                  },
                  {
                    properties: {
                      email: {
                        description: "Recipient email address.",
                        example: "marcus@shinetime.example",
                        format: "email",
                        type: "string"
                      },
                      plan_id: {
                        description: "Free variant whose membership the recipient is invited to, prefixed `plan_`.",
                        example: "plan_xxxxxxxxxxxxxx",
                        type: "string"
                      }
                    },
                    required: ["plan_id", "email"],
                    title: "InviteMembershipByEmail",
                    type: "object"
                  }
                ],
                properties: {
                  email: {
                    description: "Recipient email address. Pass exactly one of `user_id` or `email`.",
                    example: "marcus@shinetime.example",
                    format: "email",
                    type: "string"
                  },
                  plan_id: {
                    description: "Free variant whose membership the recipient is invited to, prefixed `plan_`.",
                    example: "plan_xxxxxxxxxxxxxx",
                    type: "string"
                  },
                  user_id: {
                    description: "Recipient user ID, prefixed `user_`. Pass exactly one of `user_id` or `email`.",
                    example: "user_xxxxxxxxxxxxxx",
                    type: "string"
                  }
                },
                required: ["plan_id"],
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "202": {
            content: {
              "application/json": {
                schema: {
                  properties: {
                    invitation_sent: {
                      example: true,
                      type: "boolean"
                    }
                  },
                  required: ["invitation_sent"],
                  type: "object"
                }
              }
            },
            description: "invitation accepted for delivery"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "invalid recipient"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "missing credentials"
          },
          "403": {
            $ref: "#/components/responses/Forbidden",
            description: "credential lacks the create scope or account is not enabled"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "unknown plan"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            accountApiKeyOrAppApiKeyOrAccountTokenOrAccountUserTokenAuth: [
              "membership:create"
            ]
          }
        ],
        summary: "Invite to a Membership",
        tags: ["Memberships"],
        "x-whop-credentials": [
          "account_api_key",
          "app_api_key",
          "account_token",
          "account_user_token"
        ],
        "x-codeSamples": [
          {
            lang: "TypeScript",
            source: 'import { WhopClient } from "@whop/sdk";\n\nconst client = new WhopClient({ token: "YOUR_TOKEN", apiVersionDate: "2026-08-21-1", idempotencyKey: "YOUR_IDEMPOTENCY_KEY" });\nawait client.memberships.invite({\n    plan_id: "plan_xxxxxxxxxxxxxx",\n    user_id: "user_xxxxxxxxxxxxxx"\n});\n'
          }
        ]
      }
    },
