    "/memberships/{id}/assign_affiliate": {
      post: {
        description: "Assigns an affiliate to a membership and pays them the commission you set on its future payments; past payments are not recalculated. A user who is not yet an affiliate of your account becomes one, which also requires `affiliate:create`. Send a new `commission_type` or `commission_value` for the membership's current affiliate to change their commission; a membership that already has a different affiliate returns a conflict. Works for active or trialing memberships with one recurring variant that bill through Stripe or Whop's billing engine, and not for marketplace memberships, paused payments, or a scheduled cancellation. You cannot assign yourself.",
        operationId: "assign_affiliate",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            description: "Membership ID (`mem_` tag).",
            in: "path",
            name: "id",
            required: true,
            schema: {
              type: "string"
            }
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              examples: {
                flat_fee: {
                  summary: "Assign a flat fee commission",
                  value: {
                    commission_type: "flat_fee",
                    commission_value: 5,
                    email: "affiliate@example.com"
                  }
                },
                percentage: {
                  summary: "Assign a percentage commission",
                  value: {
                    commission_type: "percentage",
                    commission_value: 20,
                    user_id: "user_xxxxxxxxxxxxx"
                  }
                }
              },
              schema: {
                properties: {
                  commission_type: {
                    description: "Whether the commission is a percentage of each payment or a fixed amount per payment.",
                    enum: ["flat_fee", "percentage"],
                    example: "percentage",
                    type: "string"
                  },
                  commission_value: {
                    description: "A whole number from 1 to 90 for `percentage`, or an amount greater than 1 in the membership currency for `flat_fee`. The payout cannot exceed 90% of the next renewal amount. Flat fees need matching billing and settlement currencies.",
                    example: 20,
                    type: "number"
                  },
                  email: {
                    description: "Email address of the user to assign. Pass exactly one of `user_id`, `email`, or `username`.",
                    example: "affiliate@example.com",
                    type: "string"
                  },
                  user_id: {
                    description: "The user to assign, prefixed `user_`. Pass exactly one of `user_id`, `email`, or `username`.",
                    example: "user_xxxxxxxxxxxxx",
                    type: "string"
                  },
                  username: {
                    description: "Whop username of the user to assign. Pass exactly one of `user_id`, `email`, or `username`.",
                    example: "affiliate",
                    type: "string"
                  }
                },
                required: ["commission_type", "commission_value"],
                type: "object"
              }
            }
          }
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  $ref: "#/components/schemas/Membership"
                }
              }
            },
            description: "affiliate assigned"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "the commission or the way the user is named is invalid"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "missing credentials"
          },
          "403": {
            $ref: "#/components/responses/Forbidden",
            description: "credential lacks the manage or affiliate scope"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "membership or user not found"
          },
          "409": {
            $ref: "#/components/responses/Conflict",
            description: "the membership already has a different affiliate or is being edited"
          },
          "503": {
            $ref: "#/components/responses/ServiceUnavailable",
            description: "the upcoming invoice could not be retrieved, so nothing was saved"
          }
        },
        security: [
          {
            bearerAuth: ["member:manage", "affiliate:update"]
          }
        ],
        summary: "Assign Affiliate to Membership",
        tags: ["Memberships"]
      }
    },
