    "/partners/fee_options": {
      get: {
        description: "Lists, per income stream, the fee a business the caller refers would be charged, how low the caller may price it, and the commission the caller earns on that stream. Answers for a referral that does not exist yet, so a referral flow can price the deal before the business is created. Requires `partner:fees:update`, since the floors a partner may price down to are only for a credential that can set them.",
        operationId: "fee_options",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          }
        ],
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  properties: {
                    object: {
                      enum: ["partner_fee_options"],
                      example: "partner_fee_options",
                      type: "string"
                    },
                    streams: {
                      description: "One entry per income stream a partner earns on.",
                      items: {
                        properties: {
                          adjustable: {
                            description: "Whether a partner may lower the fee on this stream in exchange for a cut to their commission on it.",
                            example: true,
                            type: "boolean"
                          },
                          commission_percentage: {
                            description: "The partner's commission on this stream, in percent units (30 means 30%).",
                            example: 30,
                            type: ["number", "null"]
                          },
                          fee: {
                            description: "The merchant fee behind this stream, or null when the business is charged nothing on it.",
                            properties: {
                              minimum_percentage: {
                                description: "The lowest the fee may be priced down to.",
                                example: 2.4,
                                type: "number"
                              },
                              percentage: {
                                description: "The fee in force, in percent units (2.7 means 2.7%).",
                                example: 2.7,
                                type: "number"
                              },
                              reference_region: {
                                description: "For a regionally priced fee, the region `percentage` and `minimum_percentage` describe, and the region an adjustment is quoted against. Null for a fee that is not priced per region.",
                                example: "usa",
                                type: ["string", "null"]
                              },
                              regions: {
                                description: "Every region this fee is priced for, so a caller can tell which regions a given value would reach. Empty for a fee that is not priced per region.",
                                items: {
                                  properties: {
                                    minimum_percentage: {
                                      description: "The lowest fee this region may be priced down to.",
                                      example: 2.4,
                                      type: "number"
                                    },
                                    percentage: {
                                      description: "The fee in force for this region.",
                                      example: 2.7,
                                      type: "number"
                                    },
                                    region: {
                                      description: "The region this card row prices, e.g. `usa`.",
                                      example: "usa",
                                      type: "string"
                                    }
                                  },
                                  required: [
                                    "region",
                                    "percentage",
                                    "minimum_percentage"
                                  ],
                                  type: "object"
                                },
                                type: "array"
                              }
                            },
                            required: [
                              "percentage",
                              "minimum_percentage",
                              "reference_region",
                              "regions"
                            ],
                            type: ["object", "null"]
                          },
                          income_stream: {
                            description: "The income stream these terms describe.",
                            enum: [
                              "sales",
                              "transfer",
                              "card_interchange",
                              "ad_spend",
                              "withdrawal",
                              "onboarding_reward",
                              "partner_reward",
                              "verified_partner_referral_payback"
                            ],
                            example: "sales",
                            type: "string"
                          },
                          unadjustable_reason: {
                            description: "Why the stream cannot be adjusted: `no_merchant_fee` (the business is charged nothing on it), `commission_fixed` (the commission is a flat share a fee discount may not move), `no_headroom` (already at the floor), `fee_unavailable` (no fee or rate could be resolved). Null when adjustable.",
                            enum: [
                              "no_merchant_fee",
                              "commission_fixed",
                              "no_headroom",
                              "fee_unavailable",
                              null
                            ],
                            example: "no_merchant_fee",
                            type: ["string", "null"]
                          }
                        },
                        required: [
                          "income_stream",
                          "commission_percentage",
                          "adjustable",
                          "unadjustable_reason",
                          "fee"
                        ],
                        type: "object"
                      },
                      type: "array"
                    }
                  },
                  required: ["object", "streams"],
                  type: "object"
                }
              }
            },
            description: "fee terms retrieved"
          },
          "403": {
            $ref: "#/components/responses/Forbidden",
            description: "credential cannot set partner fees"
          }
        },
        security: [
          {
            oauthTokenAuth: ["partner:basic:read", "partner:fees:update"]
          }
        ],
        summary: "Retrieve the fee terms a partner can offer",
        tags: ["Partners"],
        "x-whop-credentials": ["oauth_token"],
        "x-mint": {
          metadata: {
            title: "Retrieve the Fee Terms a Partner Can Offer",
            sidebarTitle: "Retrieve the Fee Terms a Partner Can Offer"
          }
        }
      }
    },
