    "/shipments/lookup": {
      post: {
        description: "Finds the delivery for a purchase from an account with customer tracking turned on, using exactly one order or tracking number plus the buyer's current receipt email. No authentication is required and no sign-in or session is created. Email matching ignores case and surrounding whitespace, but dots and +tags must match. Every miss returns the same 404: an unknown account, tracking turned off, a wrong number or email, an unpaid order or a purchase with nothing to ship. `shipment` is `null` while a paid physical purchase has no tracking yet. Limited to 30 attempts per five minutes per client IP. Responses are never cached or replayed with Idempotency-Key.",
        operationId: "lookup",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  account_id: {
                    description: "The selling account, prefixed `biz_`.",
                    example: "biz_xxxxxxxxxxxxxx",
                    maxLength: 255,
                    type: "string"
                  },
                  email: {
                    description: "The buyer's current receipt email.",
                    example: "marcus@shinetime.example",
                    format: "email",
                    maxLength: 254,
                    type: "string"
                  },
                  order_number: {
                    description: "The payment ID prefixed `pay_`, or the order number printed on the receipt (optional leading `#`). Supply this or `tracking_number`, not both.",
                    example: "pay_xxxxxxxxxxxxxx",
                    maxLength: 255,
                    type: "string"
                  },
                  tracking_number: {
                    description: "The exact carrier tracking number. Supply this or `order_number`, not both.",
                    maxLength: 255,
                    type: "string"
                  }
                },
                required: ["account_id", "email"],
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  $ref: "#/components/schemas/ShipmentLookup"
                }
              }
            },
            description: "shipment found"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "invalid lookup"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "shipment not found"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [],
        summary: "Look Up Shipment",
        tags: ["Shipments"]
      }
    },
