    "/users/me/passkeys/challenge": {
      post: {
        description: "Mints the challenge a browser needs to run a WebAuthn ceremony against the authenticated user's own passkeys. A `registration` challenge enrolls a new passkey; a `deletion` challenge is bound to the one passkey named by `passkey_id` and proves the user still holds it. Challenges are single-use and expire 5 minutes after they are issued, so send a fresh `Idempotency-Key` per ceremony \u2014 a replayed key returns the original challenge, which may already have expired. Requires a user session.",
        operationId: "challenge",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  challenge_type: {
                    description: "The ceremony this challenge is for.",
                    enum: ["registration", "deletion"],
                    example: "registration",
                    type: "string"
                  },
                  passkey_id: {
                    description: "The passkey the ceremony targets, prefixed `wcred_`. Required when `challenge_type` is `deletion`, ignored otherwise.",
                    example: "wcred_xxxxxxxxxxxxxx",
                    type: "string"
                  }
                },
                required: ["challenge_type"],
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  properties: {
                    challenge: {
                      description: "The challenge to pass to the WebAuthn ceremony, base64url-encoded without padding.",
                      example: "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
                      type: "string"
                    }
                  },
                  required: ["challenge"],
                  type: "object"
                }
              }
            },
            description: "challenge minted"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "the request parameters are invalid"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "missing or invalid authentication"
          },
          "403": {
            $ref: "#/components/responses/Forbidden",
            description: "the credential is not a user session"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "the passkey is not the caller's own"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            whopSessionAuth: []
          }
        ],
        summary: "Create Challenge",
        tags: ["Users"],
        "x-whop-credentials": [],
        "x-whop-docs-subgroup": "Passkeys",
        "x-codeSamples": [
          {
            lang: "TypeScript",
            source: 'import { WhopClient } from "@whop/sdk";\n\nconst client = new WhopClient({ token: "YOUR_TOKEN", apiVersionDate: "2026-08-21-1", idempotencyKey: "YOUR_IDEMPOTENCY_KEY" });\nawait client.users.passkeys.challenge({\n    challenge_type: "registration"\n});\n'
          }
        ]
      }
    },
