      post: {
        description: "Creates a pricing variant for a product, defining the billing interval, price, and availability customers buy it with.",
        operationId: "create",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  account_id: {
                    description: "The unique identifier of the account to create this variant for. Required when authenticating as a user; an account API key supplies its own account.",
                    example: "biz_xxxxxxxxxxxxxx",
                    type: "string"
                  },
                  adaptive_pricing_enabled: {
                    description: "Whether this variant accepts local currency payments via adaptive pricing.",
                    example: true,
                    type: ["boolean", "null"]
                  },
                  attributes: {
                    description: 'Attribute values that make this variant one variant of its product, as a map of attribute name to value, e.g. `{"size": "Large", "color": "Blue"}`. Names are normalized to snake_case identifiers (`Ring Size` becomes `ring_size`) and come back in alphabetical order. Every variant on a product must carry the same attribute names and a distinct set of values. Send `null` to make the variant an ordinary pricing option again.',
                    example: {
                      color: "Blue",
                      size: "Large"
                    },
                    type: ["object", "null"]
                  },
                  billing_period: {
                    description: "Recurring billing interval in days, such as 30 for monthly or 365 for annual.",
                    example: 30,
                    type: ["integer", "null"]
                  },
                  checkout_styling: {
                    description: "Checkout styling overrides for this variant.",
                    example: {
                      background_color: "#0f172a",
                      border_style: "rounded",
                      button_color: "#f59e0b",
                      font_family: "roboto"
                    },
                    type: ["object", "null"]
                  },
                  currency: {
                    description: "The three-letter ISO currency code for the variant's pricing. Defaults to USD.",
                    example: "usd",
                    type: "string"
                  },
                  custom_fields: {
                    description: "An array of custom field definitions to collect from customers at checkout. Omitting this field clears existing custom fields.",
                    items: {
                      properties: {
                        field_type: {
                          description: "The type of the custom field.",
                          enum: ["text"],
                          example: "text",
                          type: "string"
                        },
                        id: {
                          description: "The ID of the custom field (if being updated).",
                          example: "field_xxxxxxxxxxxxxx",
                          type: "string"
                        },
                        name: {
                          description: "The name of the custom field.",
                          example: "Vehicle make and model",
                          type: "string"
                        },
                        order: {
                          description: "The order of the field.",
                          example: 1,
                          type: "integer"
                        },
                        placeholder: {
                          description: "An example response displayed in the input field.",
                          example: "2021 Audi S5",
                          type: ["string", "null"]
                        },
                        required: {
                          description: "Whether or not the field is required.",
                          example: true,
                          type: "boolean"
                        }
                      },
                      type: "object"
                    },
                    type: ["array", "null"]
                  },
                  description: {
                    description: "A text description of the variant displayed to customers on the product page.",
                    example: "Two hand washes a month, interior vacuum, and a quarterly sealant top-up.",
                    type: ["string", "null"]
                  },
                  expiration_days: {
                    description: "Access duration in days before the membership expires.",
                    example: 365,
                    type: ["integer", "null"]
                  },
                  image: {
                    description: "An image displayed on the product page to represent this variant.",
                    properties: {
                      direct_upload_id: {
                        example: "eyJfcmFpbHMiOnsiZGF0YSI6MSwicHVyIjoiYmxvYl9pZCJ9fQ==--xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
                        type: "string"
                      },
                      id: {
                        example: "file_xxxxxxxxxxxxxx",
                        type: "string"
                      }
                    },
                    type: ["object", "null"]
                  },
                  initial_price: {
                    description: "Initial amount charged in the variant's currency, e.g. 10.43 for $10.43. A paid fiat variant charges at least 1.00 in its currency; use 0 for free.",
                    example: 0,
                    type: ["number", "null"]
                  },
                  internal_notes: {
                    description: "Private notes visible only to the account owner. Not shown to customers.",
                    example: "Maintenance tier. Upsell the interior shampoo add-on at renewal.",
                    type: ["string", "null"]
                  },
                  metadata: {
                    description: "Custom key-value pairs to store on the variant. Included in webhook payloads for payment and membership events. Max 50 keys, 100 chars per key, 500 chars per string value. The reserved keys `custom_cta` (a checkout call-to-action button label \u2014 one of the product custom CTA values, e.g. `subscribe`, `get_offer`) and `custom_cta_url` (a URL the button links to; web or `tel:`) override the product's call to action for this variant and are validated on save.",
                    example: {
                      bay: "2",
                      custom_cta: "subscribe",
                      custom_cta_url: "https://shinetime.example/wash-club",
                      route: "north-austin"
                    },
                    type: ["object", "null"]
                  },
                  override_tax_type: {
                    description: "Override the default tax classification for this specific variant.",
                    example: "inclusive",
                    type: "string"
                  },
                  payment_method_configuration: {
                    description: "Explicit payment method configuration for the variant. When not provided, the account's defaults apply. Send at least one of `enabled` or `disabled`; an omitted one is empty.",
                    properties: {
                      disabled: {
                        description: "Payment method types explicitly disabled for this variant \u2014 the `type` values from the payment method types catalogue. Types Whop no longer offers, and the read-only `unknown` placeholder, are dropped.",
                        example: ["paypal"],
                        items: {
                          $ref: "#/components/schemas/PaymentMethodTypes"
                        },
                        type: "array"
                      },
                      enabled: {
                        description: "Payment method types explicitly enabled for this variant \u2014 the `type` values from the payment method types catalogue. Types Whop no longer offers, and the read-only `unknown` placeholder, are dropped.",
                        example: ["card"],
                        items: {
                          $ref: "#/components/schemas/PaymentMethodTypes"
                        },
                        type: "array"
                      },
                      include_platform_defaults: {
                        example: true,
                        type: "boolean"
                      }
                    },
                    type: ["object", "null"]
                  },
                  plan_type: {
                    description: "Variant billing type, such as `one_time` or `renewal`.",
                    example: "renewal",
                    type: "string"
                  },
                  product_id: {
                    description: "The unique identifier of the product to attach this variant to.",
                    example: "prod_xxxxxxxxxxxxxx",
                    type: "string"
                  },
                  release_method: {
                    description: "Sales method for this variant.",
                    example: "buy_now",
                    type: "string"
                  },
                  renewal_price: {
                    description: "The amount charged each billing period for recurring variants, in the variant's currency. A paid fiat variant charges at least 1.00 in its currency.",
                    example: 59,
                    type: ["number", "null"]
                  },
                  sku: {
                    description: "Stock keeping unit for this variant. Maximum 100 characters. Free text, not enforced unique.",
                    example: "TEE-LARGE-BLUE",
                    type: ["string", "null"]
                  },
                  split_pay_required_payments: {
                    description: "Installment payments required before the subscription pauses.",
                    example: 4,
                    type: ["integer", "null"]
                  },
                  stock: {
                    description: "The maximum number of units available for purchase. Ignored when unlimited_stock is true.",
                    example: 25,
                    type: ["integer", "null"]
                  },
                  three_ds_level: {
                    description: "3D Secure behavior for supported on-session card payments. `mandate_challenge` requires a 3DS challenge before payment processing; `mandate_if_required` mandates a challenge only when the payment processor requires it; `frictionless_if_required` uses the regular frictionless 3DS flow. Payments of $1,000 or more use `mandate_if_required` unless `mandate_challenge` is selected. Risk and authentication recovery requirements can override the preference. Send `null` to inherit the account default.",
                    enum: [
                      "mandate_challenge",
                      "mandate_if_required",
                      "frictionless_if_required",
                      null
                    ],
                    example: "frictionless_if_required",
                    type: ["string", "null"]
                  },
                  title: {
                    description: "The display name of the variant shown to customers on the product page. Maximum 30 characters.",
                    example: "Unlimited Wash Club",
                    maxLength: 30,
                    type: ["string", "null"]
                  },
                  trial_period_days: {
                    description: "Free trial duration before the first recurring charge.",
                    example: 7,
                    type: ["integer", "null"]
                  },
                  unlimited_stock: {
                    description: "Whether the variant has unlimited stock. When true, the stock field is ignored.",
                    example: false,
                    type: ["boolean", "null"]
                  },
                  visibility: {
                    description: "Whether the variant is visible to customers or hidden from public view.",
                    example: "visible",
                    type: "string"
                  }
                },
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  $ref: "#/components/schemas/Variant"
                }
              }
            },
            description: "variant created"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "invalid parameters"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "missing or invalid authentication"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            bearerAuth: ["plan:create"]
          }
        ],
        summary: "Create Variant",
        tags: ["Variants"],
        "x-mint": {
          metadata: {
            sidebarTitle: "Create"
          }
        }
      }
