    "/webhooks/{id}/replay": {
      post: {
        description: "Re-sends the webhook's past deliveries within a time window, optionally limited to specific events or to failed deliveries. Use it to recover events your endpoint missed. The replay runs asynchronously and nothing about it is stored: each re-send appears as a new entry in the webhook's delivery log. Each matching message is re-sent once, with its original `webhook-id` unless you pass `regenerate_ids`. Only available for enabled webhooks on API version `v1`; deliveries are retained for 30 days.",
        operationId: "replay",
        parameters: [
          {
            $ref: "#/components/parameters/ApiVersionDate"
          },
          {
            description: "Webhook ID, prefixed `hook_`.",
            in: "path",
            name: "id",
            required: true,
            schema: {
              type: "string"
            }
          },
          {
            $ref: "#/components/parameters/IdempotencyKey"
          }
        ],
        requestBody: {
          content: {
            "application/json": {
              schema: {
                properties: {
                  events: {
                    description: "Only replay these event types, in dot form (for example `payment.succeeded`). Omit to include every event.",
                    items: {
                      type: "string"
                    },
                    type: "array"
                  },
                  failed_only: {
                    description: "Only replay messages whose most recent delivery attempt in the window failed. Defaults to false. Best-effort: a message whose attempts span processing batches can still be re-sent \u2014 replays keep the original `webhook-id` by default, so consumers that deduplicate are unaffected.",
                    example: true,
                    type: "boolean"
                  },
                  regenerate_ids: {
                    description: "Re-send each replayed message under a freshly generated `webhook-id` (in both the envelope and the signed headers) instead of its original one. Defaults to false. Use this when your endpoint deduplicates on `webhook-id` and you want it to process the replays as new messages.",
                    example: true,
                    type: "boolean"
                  },
                  sent_after: {
                    description: "Start of the delivery window to replay, as an ISO 8601 timestamp. Clamped to the 30-day delivery retention.",
                    example: "2026-01-01T12:00:00.000Z",
                    type: "string"
                  },
                  sent_before: {
                    description: "End of the delivery window to replay, as an ISO 8601 timestamp. Defaults to now.",
                    type: "string"
                  }
                },
                required: ["sent_after"],
                type: "object"
              }
            }
          },
          required: true
        },
        responses: {
          "200": {
            content: {
              "application/json": {
                schema: {
                  example: {
                    queued: true
                  },
                  properties: {
                    queued: {
                      description: "Whether the replay was accepted. Watch the webhook's delivery log for the re-sends.",
                      example: true,
                      type: "boolean"
                    }
                  },
                  required: ["queued"],
                  type: "object"
                }
              }
            },
            description: "replay queued"
          },
          "400": {
            $ref: "#/components/responses/InvalidParameters",
            description: "missing sent_after"
          },
          "401": {
            $ref: "#/components/responses/Unauthorized",
            description: "missing or invalid authentication"
          },
          "403": {
            $ref: "#/components/responses/Forbidden",
            description: "credential lacks the required webhook-management scope"
          },
          "404": {
            $ref: "#/components/responses/NotFound",
            description: "no webhook with that ID"
          },
          "409": {
            $ref: "#/components/responses/Conflict"
          }
        },
        security: [
          {
            accountApiKeyOrAppApiKeyOrAccountTokenOrAccountUserTokenAuth: [
              "developer:manage_webhook"
            ]
          }
        ],
        summary: "Replay Deliveries in a Range",
        tags: ["Webhooks"],
        "x-whop-credentials": [
          "account_api_key",
          "app_api_key",
          "account_token",
          "account_user_token"
        ],
        "x-codeSamples": [
          {
            lang: "TypeScript",
            source: 'import { WhopClient } from "@whop/sdk";\n\nconst client = new WhopClient({ token: "YOUR_TOKEN", apiVersionDate: "2026-08-21-1", idempotencyKey: "YOUR_IDEMPOTENCY_KEY" });\nawait client.webhooks.replay({\n    id: "id",\n    sent_after: "2026-01-01T12:00:00.000Z"\n});\n'
          }
        ]
      }
    },
