          "title",
          "description",
          "status",
          "currency",
          "gross_reward_amount",
          "net_reward_amount",
          "affiliate_share_amount",
          "budget_amount",
          "gross_paid_out_amount",
          "accepted_submissions_limit",
          "accepted_submissions_per_user_limit",
          "accepted_submissions_count",
          "unresolved_submissions_count",
          "viewer_accepted_submissions_count",
          "spots_remaining",
