      DisputeEvidenceDocument: {
        properties: {
          blurhash: {
            description: "BlurHash placeholder for an image or video. Null when unavailable or removed by moderation.",
            example: "LA6bDXT$E3b:R6i+RibEIWbp%ej1",
            type: ["string", "null"]
          },
          content_type: {
            description: "The uploaded file's MIME type. Uploads are restricted to the types the processor accepts, and rejected without one \u2014 never null.",
            enum: [
              "application/pdf",
              "application/json",
              "image/jpeg",
              "image/png",
              "image/webp",
              null
            ],
            example: "image/png",
            type: ["string", "null"]
          },
          created_at: {
            description: "When the file was created, as an ISO 8601 timestamp.",
            example: "2026-01-01T12:00:00.000Z",
            type: "string"
          },
          document_type: {
            description: "What this document proves, in the processor's own evidence vocabulary. `return_policy`, `cancellation_policy`, and `terms_of_service` are the seller's policy documents \u2014 uploading one overrides the account's copy for this dispute (`return_policy`, `cancellation_policy`, and `customer_communication` also override the matching fixed evidence slot). `shipping_policy` is the seller's shipping terms. `customer_communication` is correspondence with the buyer \u2014 a support thread or chat log. `product_image` is a photo of the product or service the buyer received. `physical_fulfillment` is proof a physical order shipped and arrived; `digital_fulfillment` is proof the buyer accessed a digital product. `customer_order_history` is the buyer's past orders with this seller; `prior_transactions` is their broader payment history across the platform, for a fraud defense. `customer_session` is checkout forensics \u2014 IP, device fingerprint, AVS/CVV, 3D Secure result. `subscription` is membership lifecycle evidence \u2014 renewals, cancellation, reminders sent.",
            enum: [
              "return_policy",
              "shipping_policy",
              "cancellation_policy",
              "terms_of_service",
              "physical_fulfillment",
              "customer_order_history",
              "product_image",
              "prior_transactions",
              "customer_session",
              "digital_fulfillment",
              "subscription",
              "customer_communication"
            ],
            example: "customer_order_history",
            type: "string"
          },
          duration_seconds: {
            description: "Audio or video duration in seconds. Null when unavailable or removed by moderation.",
            example: null,
            type: ["number", "null"]
          },
          filename: {
            description: "The original filename, including its extension.",
            example: "customer-order-history.png",
            type: ["string", "null"]
          },
          height: {
            description: "Image or video height in pixels. Null when unavailable or removed by moderation.",
            example: 100,
            type: ["integer", "null"]
          },
          id: {
            description: "The file's ID, prefixed `file_`.",
            example: "file_xxxxxxxxxxxxxx",
            type: "string"
          },
          multipart_chunk_size: {
            description: "The byte size each part (except the last) must be. Present only on create, and only for multipart uploads.",
            type: ["integer", "null"]
          },
          multipart_upload_id: {
            description: "The ID of the multipart upload, passed back to `complete`. Present only on create, and only for multipart uploads.",
            type: ["string", "null"]
          },
          multipart_upload_urls: {
            items: {
              $ref: "#/components/schemas/FileMultipartUrl",
              description: "The presigned URL for each part. Present only on create, and only for multipart uploads."
            },
            type: ["array", "null"]
          },
          object: {
            description: "The type of this object, always `file`.",
            example: "file",
            type: "string"
          },
          removed_by_moderation: {
            description: "Whether moderation removed the file. When true, `url` serves a replacement image; filename, size, and content type still describe the original file.",
            example: false,
            type: "boolean"
          },
          size: {
            description: "The file size in bytes. `null` until the upload has finished.",
            example: 1024,
            type: ["integer", "null"]
          },
          upload_headers: {
            description: "Headers to send with the upload PUT. Present only on create.",
            type: "object"
          },
          upload_status: {
            description: "Where the file is in its upload lifecycle.",
            enum: ["pending", "processing", "ready", "failed"],
            example: "ready",
            type: "string"
          },
          upload_url: {
            description: "Presigned URL to PUT the file's bytes to. Present only on create, and only for single-part uploads.",
            type: ["string", "null"]
          },
          url: {
            description: "A URL to download the file: a permanent CDN URL for public files, a signed expiring URL for private ones. Null until the upload has finished; a replacement image URL when removed by moderation.",
            example: "https://whop-assets-example.s3.amazonaws.com/uploads/image/2026-01-01/xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx",
            type: ["string", "null"]
          },
          visibility: {
            description: "`public` files are served via an unsigned CDN URL; `private` files via a signed, expiring URL.",
            enum: ["public", "private"],
            example: "public",
            type: "string"
          },
          waveform_url: {
            description: "Audio waveform URL. Null when unavailable or removed by moderation.",
            example: null,
            type: ["string", "null"]
          },
          width: {
            description: "Image or video width in pixels. Null when unavailable or removed by moderation.",
            example: 100,
            type: ["integer", "null"]
          }
        },
        required: [
          "object",
          "id",
          "filename",
          "content_type",
          "size",
          "url",
          "removed_by_moderation",
          "upload_status",
          "visibility",
          "created_at",
          "width",
          "height",
          "blurhash",
          "duration_seconds",
          "waveform_url",
          "document_type"
        ],
        type: "object"
      },
