      PixelValidation: {
        properties: {
          affiliate_tracking_detected: {
            description: "Whether an affiliate tracking SDK was found on the page at `url`. Supported platforms: Everflow.",
            example: false,
            type: "boolean"
          },
          firing_data_ok: {
            description: "False when the event lookup failed, meaning `host_events` and `last_seen_days` are incomplete.",
            example: true,
            type: "boolean"
          },
          host_events: {
            items: {
              description: "Conversion event names detected on the requested page or fired recently anywhere on its hostname or final redirect hostname.",
              example: "lead",
              type: "string"
            },
            type: "array"
          },
          installed: {
            description: "Whether the pixel was seen. Without a `url` this answers for the whole account: true when it has sent events recently. With a `url` it answers for THAT page only \u2014 true when the page is hosted on Whop, when the page itself has sent events recently, or when the pixel was found in its source. Events the account sent from other pages do not make a given `url` installed.",
            example: false,
            type: "boolean"
          },
          last_fired_days: {
            description: 'Event name to whole days since that event last fired, e.g. `{ "lead": 3 }`. Carries events that fired too long ago to count as installed, so you can prompt to re-check rather than report them missing.',
            example: {
              lead: 2
            },
            type: "object"
          },
          last_seen_days: {
            description: "Days since the pixel last sent an event, within a 30-day window. `null` when it hasn't sent one in that window \u2014 which includes a pixel installed moments ago.",
            example: 2,
            type: ["number", "null"]
          },
          native_tracking: {
            description: "True when `url` is hosted on Whop, so no pixel snippet is required.",
            example: false,
            type: "boolean"
          },
          page_events: {
            items: {
              description: "Conversion event names detected on the requested page, from its recent events or its source and linked scripts.",
              example: "lead",
              type: "string"
            },
            type: "array"
          },
          reachable: {
            description: "Whether the page could be loaded. `null` when the request included no URL, and `true` when events settled the answer without a fetch.",
            example: true,
            type: ["boolean", "null"]
          },
          url: {
            description: "The URL that was checked, after normalization. `null` when the request didn't include one.",
            example: "https://shinetime.example/",
            type: ["string", "null"]
          }
        },
        required: [
          "installed",
          "url",
          "reachable",
          "last_seen_days",
          "page_events",
          "host_events",
          "native_tracking",
          "last_fired_days",
          "firing_data_ok",
          "affiliate_tracking_detected"
        ],
        type: "object"
      },
