            items: {
              description: "What you can do to this case right now, named for the endpoint that does it. Resolved for the calling credential, so a merchant and a customer reading the same case see their own options.",
              enum: [
                "accept",
                "deny",
                "request_info",
                "reply",
                "appeal",
                "withdraw"
              ],
              example: "accept",
              type: "string"
            },
