// src/api/browser-links.ts
import { confirm, isCancel as isCancel2 } from "@clack/prompts";

// src/lib/open-browser.ts
import { execFile } from "child_process";
function openBrowser(url2) {
  const ignore = () => {
  };
  if (process.platform === "darwin") {
    execFile("open", [url2], ignore);
  } else if (process.platform === "win32") {
    const escaped = url2.replace(/[&|<>^]/g, "^$&");
    execFile(
      "cmd.exe",
      ["/d", "/s", "/c", "start", '""', escaped],
      { windowsVerbatimArguments: true },
      ignore
    );
  } else {
    execFile("xdg-open", [url2], ignore);
  }
}

// src/api/browser-links.ts
var ACTION_URL_FIELDS = [
  "authorize_url",
  "session_url",
  "deposit_url",
  "checkout_url"
];
function findActionUrl(payload) {
  if (payload == null || typeof payload !== "object" || Array.isArray(payload)) {
    return null;
  }
  const rec = payload;
  for (const field of ACTION_URL_FIELDS) {
    const value = rec[field];
    if (typeof value === "string" && /^https?:\/\//i.test(value)) return value;
  }
  return null;
}
function actionUrlNotice(url2, outcome) {
  switch (outcome) {
    case "opened":
      return `Opened your browser to complete this step:
${url2}
If it didn't open, visit the link above.`;
    case "manual":
      return `Complete this step in your browser:
${url2}`;
    case "agent":
      return `Action required: open this link in the user's browser to complete this step:
${url2}`;
  }
}
async function confirmOpenInBrowser(url2) {
  const answer = await confirm({
    message: `This step needs to be completed in your browser. Open ${url2} now?`
  });
  return !isCancel2(answer) && answer === true;
}
async function announceActionUrl(url2, {
  isTTY = process.stdout.isTTY === true && process.stdin.isTTY === true,
  confirmOpen = confirmOpenInBrowser,
  open = openBrowser,
  print = (text4) => process.stderr.write(`${text4}
`)
} = {}) {
  if (!isTTY) {
    print(actionUrlNotice(url2, "agent"));
    return;
  }
  const shouldOpen = await confirmOpen(url2);
  if (shouldOpen) open(url2);
  print(actionUrlNotice(url2, shouldOpen ? "opened" : "manual"));
}

